BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the general purpose of a ''squeezing/mangle'' roller unit placed after a washing/rinsing bath in a continuous wet-processing line?', '["To remove excess water from the fabric before it proceeds to the next stage (like drying or the next chemical bath), controlling wet pickup and saving energy in subsequent drying","To apply the final dye color to the fabric","To insert twist into the yarn within the fabric structure","To measure the exact final GSM of the fabric"]'::jsonb, 'To remove excess water from the fabric before it proceeds to the next stage (like drying or the next chemical bath), controlling wet pickup and saving energy in subsequent drying', 'Squeeze/mangle rollers press out excess water after a wet stage, reducing the amount of water that must later be evaporated during drying (saving energy) and controlling how much liquor carries over into the next process stage.', 1, '{"squeeze-mangle-rollers"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is ''rinsing efficiency'' (how thoroughly residual chemicals are washed out between process steps) important for consistent multi-stage wet processing?', '["Carryover of residual chemicals from one stage into the next can interfere with subsequent process chemistry, causing inconsistent or unexpected results","Rinsing efficiency has no bearing on any subsequent process step''s outcome","Thorough rinsing always wastes water with no quality benefit whatsoever","Residual chemical carryover always improves the next process step''s performance"]'::jsonb, 'Carryover of residual chemicals from one stage into the next can interfere with subsequent process chemistry, causing inconsistent or unexpected results', 'If chemicals from a prior stage (like leftover alkali from scouring, or hypochlorite from bleaching) aren''t thoroughly rinsed out, they can carry over and interfere with the chemistry of the NEXT process (e.g., unexpected pH shifts affecting dye uptake) — making consistent rinsing an important, easily overlooked control point in multi-stage processing.', 2, '{"rinsing-efficiency"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is a ''batch tumbler'' (rotary drum) sometimes used for as a mechanical finishing step on knitted or woven fabric?', '["Tumbling fabric in a rotating drum (often with heat) to relax the fabric structure, soften handle, and sometimes create a slightly textured surface","Applying the initial dye color to completely undyed fabric","Cutting fabric into individual garment pattern pieces","Measuring the exact tensile strength of the fabric"]'::jsonb, 'Tumbling fabric in a rotating drum (often with heat) to relax the fabric structure, soften handle, and sometimes create a slightly textured surface', 'Tumble finishing (mechanically tumbling fabric, often with heat and sometimes softening agents, in a rotating drum) relaxes internal fabric stresses, softens the hand-feel, and can impart a slightly textured, more casual surface appearance — commonly used for garment-washed or casual-look fabrics.', 1, '{"tumble-finishing"}'::text[]);
COMMIT;
